parameters.jsCode:
// Parse Claude's JSON-Antwort (text content), splitte in Antrag-Payload
// + Belegpositionen, und ergänze Pflicht-Defaults.
//
// WICHTIG seit Audit 2026-05-24 (Achse A P0-1):
// Migration 016 hat die Kostenspalten aus apl2.antraege in apl2.belegposition
// verschoben. Wenn wir die Kosten als Top-Level-Property in den antraege-
// INSERT pushen, ignoriert PostgREST sie still → Datenverlust. Stattdessen
// erzeugen wir hier einen separaten belegpositionen[]-Array, der nach dem
// antraege-INSERT in separaten Calls geschrieben wird.
//
// foerderbereich: Default 'begegnungszentren' (Robert-Entscheidung 2026-05-24:
// APL 2 wird primär als BZ subsumiert; Sachbearbeiter kann überschreiben).

const input = $input.first().json;
const content = input.content?.[0]?.text;
if (!content) {
  throw new Error('Claude lieferte keinen Text-Content zurück: ' + JSON.stringify(input));
}
let extr;
try {
  const cleaned = content.trim().replace(/^```json\n?/, '').replace(/\n?```$/, '');
  extr = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Claude-Antwort ist kein JSON: ' + content.slice(0, 500));
}

// Kostenfelder aus dem Antrag-Payload entfernen — sie gehen separat in belegposition
const betriebskosten = extr.betriebskosten_vorjahr_euro;
const personalkosten = extr.personalkosten_vorjahr_euro;
const miete_monat    = extr.monatliche_miete_euro;
delete extr.betriebskosten_vorjahr_euro;
delete extr.personalkosten_vorjahr_euro;
delete extr.monatliche_miete_euro;

// Antrag-Defaults
extr.submitted_language = 'de';
extr.antragsdatum = extr.antragsdatum || new Date().toISOString().slice(0, 10);
extr.status = 'eingegangen';
// Förderbereich-Default (Sachbearbeiter kann ändern)
if (!extr.foerderbereich) extr.foerderbereich = 'begegnungszentren';

// Bemessungs-Felder bleiben NULL — PDF fragt sie nicht ab. UE3 zeigt entsprechende
// Hinweise. geforderte_foerdersumme_euro bleibt NULL — Sachbearbeitung beziffert.

// Belegposition-Array bauen — nur Positionen mit Wert > 0
const belegpositionen = [];
if (typeof betriebskosten === 'number' && betriebskosten > 0) {
  belegpositionen.push({
    belegtyp: 'betriebskosten',
    bezeichnung: 'Betriebskosten Vorjahr (aus OCR)',
    betrag_euro: betriebskosten
  });
}
if (typeof personalkosten === 'number' && personalkosten > 0) {
  belegpositionen.push({
    belegtyp: 'personalkosten',
    bezeichnung: 'Personalkosten Vorjahr (aus OCR)',
    betrag_euro: personalkosten
  });
}
if (typeof miete_monat === 'number' && miete_monat > 0) {
  // PDF fragt MONATLICH ab; in DB landet Jahressumme
  belegpositionen.push({
    belegtyp: 'miete',
    bezeichnung: 'Jahresmiete (aus OCR: ' + miete_monat + ' € × 12)',
    betrag_euro: miete_monat * 12
  });
}

return [{
  json: {
    extrahiert: extr,
    belegpositionen: belegpositionen,
    einreichung_id: $('Webhook Trigger (Supabase NOTIFY)').first().json.body.einreichung_id
  }
}];

// Belegpositionen mit antrag_id annotieren — der vorhergehende INSERT-Knoten
// liefert die neue Antrag-ID in $json[0].id. Wir produzieren eine Liste, die
// der nachfolgende Loop-Over-Items-INSERT abarbeitet.

const antragId = $input.first().json[0]?.id;
if (!antragId) {
  throw new Error('INSERT apl2.antraege lieferte keine ID zurück: ' + JSON.stringify($input.first().json));
}
const beleg = $('Parse JSON + Defaults + Belegpositionen-Split').first().json.belegpositionen || [];
if (beleg.length === 0) {
  // Keine Belegpositionen — leeres Array passieren lassen, nächster HTTP-Node
  // wird nicht ausgeführt (siehe IF-Bedingung dort).
  return [{ json: { antrag_id: antragId, belegpositionen: [], _skip_belegposition: true } }];
}
return beleg.map(b => ({
  json: { ...b, antrag_id: antragId, _skip_belegposition: false }
}));

// Prüft ob die Einreichung eine Anlage 1 (Wochenplan-PDF) enthält.
// REST-GET-Antwort: [{ anlage_1_storage_path: '2026/05/<uuid>.pdf' }] oder [{ anlage_1_storage_path: null }].
const row = ($input.first().json || [])[0] || {};
const path = row.anlage_1_storage_path;
const antragId = $('Annotate Belegpositionen mit antrag_id').first().json.antrag_id;
return [{
  json: {
    antrag_id: antragId,
    anlage_1_storage_path: path || null,
    _has_anlage_1: !!path
  }
}];

