// Parse Claude's JSON-Array-Antwort, validiere Wochentag-Werte,
// annotiere mit antrag_id, gib eine Liste von INSERT-Payloads zurück.
//
// DB-Schema (Migration 015):
//   apl2.oeffnungszeit(antrag_id uuid, wochentag text CHECK in mo|di|mi|do|fr|sa|so,
//                      oeffnungszeit text, angebot text)
//   PK = (antrag_id, wochentag) → pro Antrag max 7 Zeilen, keine Duplikate.

const input = $input.first().json;
const content = input.content?.[0]?.text;
if (!content) {
  throw new Error('Claude (Anlage 1) lieferte keinen Text-Content zurück');
}
let rows;
try {
  const cleaned = content.trim().replace(/^```json\n?/, '').replace(/\n?```$/, '');
  rows = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Anlage-1-Antwort ist kein JSON-Array: ' + content.slice(0, 500));
}
if (!Array.isArray(rows)) {
  throw new Error('Anlage-1-Antwort ist kein Array: ' + content.slice(0, 200));
}

const antragId = $('Decide Anlage-1-Branch').first().json.antrag_id;
const validTage = ['mo','di','mi','do','fr','sa','so'];
// Deduplizieren nach wochentag — falls Claude versehentlich Duplikate liefert,
// nehmen wir den ersten Treffer (PK würde sonst beim INSERT crashen).
const seen = new Set();
const out = [];
for (const r of rows) {
  const tag = (r.wochentag || '').toLowerCase();
  if (!validTage.includes(tag)) continue;
  if (seen.has(tag)) continue;
  seen.add(tag);
  out.push({
    antrag_id: antragId,
    wochentag: tag,
    oeffnungszeit: r.oeffnungszeit || null,
    angebot: r.angebot || null
  });
}
if (out.length === 0) {
  return [{ json: { antrag_id: antragId, _skip: true } }];
}
return out.map(r => ({ json: { ...r, _skip: false } }));

